{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01", "C13", "C24", "C31", "C38", "C12"],
  "contradictory_card_ids": ["C03", "C19", "C25", "C27", "C28", "C35", "C37", "C40", "C41", "C47"],
  "prediction_basis_card_ids": ["C01", "C13", "C24", "C31", "C38", "C12"],
  "claims": [
    {
      "claim": "EM574, a closely related macrolide, has very low human oral bioavailability (~2%) inferred from a mean oral CL/F of 4500 L/h; L2 records confirm low F in rabbits (2.4–3.3% FgFh) and low F in rats/dogs due to extensive metabolism.",
      "card_ids": ["C01", "C13", "C24", "C31", "C38"]
    },
    {
      "claim": "YH4808 provides a direct human absolute F of 10.1% (range 2.3–19.3%), below the 20% threshold, though it is structurally distant from the query macrolide.",
      "card_ids": ["C12"]
    },
    {
      "claim": "L3 clarithromycin Cmax records (3.65 and 3.12 µg/mL at 500 mg BID) show that a macrolide with desosamine/cladinose-like sugars can achieve substantial oral exposure, but no F value is reported; this is a weakly contradictory context with limited transferability to the query.",
      "card_ids": ["C41", "C47"]
    },
    {
      "claim": "High-F contexts (oseltamivir ~79%, etoposide 38–52%, ER-30346 48–74% in animals, withaferin A 87% in rats, moxidectin same oral/SC in sheep) are structurally distant, species/formulation-specific, or relative comparisons and do not outweigh the macrolide-specific low-F evidence.",
      "card_ids": ["C03", "C19", "C25", "C27", "C28", "C35", "C37", "C40"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C41", "C47"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute F measurement exists for the exact query macrolide.",
    "EM574 is closely related but not identical; differences in sugar substitution, absence of HBD, and aglycone may alter absorption or metabolism.",
    "L3 clarithromycin records report Cmax only, not F, so they cannot establish threshold-relevant bioavailability.",
    "Formulation, food effects, solubility/dissolution, and first-pass enzyme contributions for the query are unknown.",
    "No quantitative permeability or metabolic stability data for the query were supplied."
  ],
  "decision_summary": "The most transferable evidence remains EM574, a macrolide with ~2% human F and low F in rabbits/rats/dogs; YH4808 adds a direct human absolute F of 10.1%. L3 clarithromycin Cmax records show oral exposure for a macrolide but lack F and are not query-specific. Prediction remains low with moderate confidence."
}

